preset.frame_eqs_eel:
q1=bass&time*.43;
q2=bass_att&time*.63;
q3=treb&time*.76;
q4=treb_att&time*.61;
q5=mid&time*.27;
q6=mid_Att&time*.23;
q7=if(Above(below(q1,q3),below(q3,q1)),q3-q2*sin(Q1),q2-q1*sin(q3));
q8=if(Above(below(q2,q3),below(q2,q1)),q2-q1*sin(Q5),q5-q6*sin(q7));
wave_r=wave_r+.6*sin(q1);
wave_b=wave_b+.3*sin(q2);
wave_g=wave_g*sin(Q7);
ob_r=wave_r;
ob_b=wave_B;
ob_g=wave_g;
ib_r=wave_r;
ib_g=wave_b;
ib_b=wave_g;

preset.pixel_eqs_eel:
rad_cycle=rad*rad*x*60*rad*sin(q6)+1;
d=.03*(sin(rad*3.14*sin(q3)))+1;
r=d-.03*(sin(ang*3.14*sin(q2)));
radx=below(0.3-rad+x,0.3+rad-x);
rady=below(0.3-rad+y,0.3+rad-y);
snare=below(1*rad-x-y,x-rad-.3-x-y*d*r)*sin(q1-d+r)*d*r+.01;
x2=above(x,rad)+.01;
y2=above(y,rad)+.01;
smear=if(equal(rad-.03,ang*rad),smear*sin(Q1),rot-.1*ang/2/2/2/2*Rad*sin(Rad)*sin(q3)
*sin(rad_cycle+.3*sin(q1)+.1)+.03*sin(Q2))+.01*sin(rad_cycle);
zoom=zoom-.05*sin(ang*rad*3.14*sin(q1))-.05*sin(rad*3.14*sin(Q2))+.05*sin(ang*3.14*sin(q3));
rot=rot+.03*sin(ang*3.14)*rad+.02*sin(q1-rad*x*3.14)*sin(q1);
